CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,content TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 1,title_en TEXT,content_en TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT NOT NULL,content TEXT,content_en TEXT,anchor TEXT NOT NULL,action TEXT DEFAULT 'quote',position INTEGER DEFAULT 1,published INTEGER DEFAULT 1,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS steps (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT NOT NULL,content TEXT,content_en TEXT,target TEXT DEFAULT 'sale',position INTEGER DEFAULT 1,published INTEGER DEFAULT 1,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS faqs (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT NOT NULL,content TEXT,content_en TEXT,position INTEGER DEFAULT 1,published INTEGER DEFAULT 1,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS requests (id SERIAL PRIMARY KEY,request_key TEXT UNIQUE,reference TEXT,user_id TEXT,kind TEXT NOT NULL DEFAULT 'quote',name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,municipality TEXT NOT NULL,customer_type TEXT NOT NULL DEFAULT 'residential',reason TEXT NOT NULL DEFAULT 'quote',requested_date DATE,preferred_period TEXT DEFAULT 'flexible',model TEXT,serial_number TEXT,message TEXT,language TEXT DEFAULT 'fr',status TEXT DEFAULT 'received',email_status TEXT DEFAULT 'pending',internal_notes TEXT,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());